decay_replay_constants_witness_command:
PYTHONPATH=. python3 - "{run_root}" <<'PY'
import json, sys
from pathlib import Path
run_root = Path(sys.argv[1])
log = run_root / 'd_recompute_window_diagnostic' / 'recompute_window_log.jsonl'
failures = []
if not log.is_file():
    failures.append('missing_log')
else:
    row = json.loads(next(l for l in log.read_text().splitlines() if l.strip()))
    rc = row.get('replay_constants') or {}
    if int(rc.get('decay_numerator', -1)) != 1 or int(rc.get('decay_denominator', -1)) != 2:
        failures.append('decay_not_1_over_2')
receipt = {'pass': not failures, 'failures': failures}
out = run_root / 'prelaunch' / 'decay_replay_constants_witness.json'
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(receipt, indent=2) + '\n')
if failures: raise SystemExit(1)
PY
